<script setup lang="ts">
type Speaker={id:string;label:string;enterpriseId?:string|null;anonymous?:boolean};
const props=defineProps<{speakers:Speaker[];selectedId?:string|null;readonly?:boolean}>();
const emit=defineEmits<{select:[speakerId:string];rename:[speakerId:string,label:string];merge:[sourceSpeakerId:string,targetSpeakerId:string]}>();
</script>
<template><section class="speaker-editor" aria-label="说话人编辑"><header><strong>说话人</strong><span class="muted">{{props.speakers.length}} 人</span></header><ul><li v-for="speaker in props.speakers" :key="speaker.id" :class="{selected:speaker.id===selectedId}"><button type="button" class="speaker-select" :disabled="readonly" @click="emit('select',speaker.id)"><span class="avatar">{{speaker.label.slice(0,1)}}</span><span><b>{{speaker.label}}</b><small>{{speaker.anonymous||!speaker.enterpriseId?'匿名':'已关联企业身份'}}</small></span></button><button v-if="!readonly" type="button" class="btn sm ghost" @click="emit('rename',speaker.id,speaker.label)">编辑</button></li></ul></section></template>
